2	import { supabase } from '../utils/supabase';
3	import { getMember, addRoleToMember, removeRoleFromMember } from '../utils/discord';
4	import { logger } from '../utils/logger';
5	import { RolesSyncRequest, RolesSyncResponse } from '../types/api';
6	import { Member, GenerationRole, Team, MemberTeamRelation, TeamLeader } from '../types/database';
7	
8	export const syncRoles = async (req: Request, res: Response): Promise<void> => {
9	  try {
10	    const { discord_uid } = req.body as RolesSyncRequest;
11	
12	    if (!discord_uid) {
13	      res.status(400).json({ success: false, error: 'discord_uid is required' });
14	      return;
15	    }
16	
17	    // Discordメンバーを取得
18	    const member = await getMember(discord_uid);
19	    if (!member) {
20	      res.status(404).json({ success: false, error: 'Discord member not found' });
21	      return;
22	    }
23	
24	    // DBから部員情報を取得
25	    const { data: memberData, error: memberError } = await supabase
26	      .from('members')
27	      .select('*')
28	      .eq('discord_uid', discord_uid)
29	      .single<Member>();
30	
31	    if (memberError || !memberData) {
32	      logger.error('Failed to fetch member from DB', memberError);
33	      res.status(404).json({ success: false, error: 'Member not found in database' });
34	      return;
35	    }
36	
37	    const rolesAssigned: string[] = [];
38	    const rolesRemoved: string[] = [];
39	
40	    // 1. 期生ロールの同期
41	    const { data: generationRole } = await supabase
42	      .from('generation_roles')
43	      .select('*')
44	      .eq('generation', memberData.generation)
45	      .single<GenerationRole>();
46	
47	    if (generationRole) {
48	      // 期生ロールを付与
49	      const hasRole = member.roles.cache.has(generationRole.discord_role_id);
50	      if (!hasRole) {
51	        await addRoleToMember(member, generationRole.discord_role_id);
52	        rolesAssigned.push(`${memberData.generation}期生`);
53	      }
