2	import { logger } from './logger';
3	
4	let client: Client | null = null;
5	
6	export const initializeDiscordClient = (): Client => {
7	  if (client) {
8	    return client;
9	  }
10	
11	  client = new Client({
12	    intents: [
13	      GatewayIntentBits.Guilds,
14	      GatewayIntentBits.GuildMembers,
15	    ],
16	  });
17	
18	  client.once('ready', () => {
19	    logger.info(`✅ Discord Bot is online! Logged in as ${client?.user?.tag}`);
20	  });
21	
22	  return client;
23	};
24	
25	export const getDiscordClient = (): Client => {
26	  if (!client) {
27	    throw new Error('Discord client is not initialized');
28	  }
29	  return client;
30	};
31	
32	export const loginDiscordBot = async (token: string): Promise<void> => {
33	  const discordClient = initializeDiscordClient();
34	  await discordClient.login(token);
35	};
36	
37	// Discord ギルド（サーバー）IDを環境変数から取得
38	export const getGuildId = (): string => {
39	  const guildId = process.env.DISCORD_GUILD_ID;
40	  if (!guildId) {
41	    throw new Error('DISCORD_GUILD_ID is not set in environment variables');
42	  }
43	  return guildId;
44	};
45	
46	// メンバーを取得
47	export const getMember = async (discordUid: string): Promise<GuildMember | null> => {
48	  try {
49	    const client = getDiscordClient();
50	    const guildId = getGuildId();
51	    const guild = await client.guilds.fetch(guildId);
52	    const member = await guild.members.fetch(discordUid);
53	    return member;
54	  } catch (error) {
55	    logger.error('Failed to fetch Discord member', error);
56	    return null;
57	  }
58	};
59	
60	// ロールを取得
61	export const getRole = async (roleId: string): Promise<Role | null> => {
62	  try {
63	    const client = getDiscordClient();
64	    const guildId = getGuildId();
65	    const guild = await client.guilds.fetch(guildId);
66	    const role = await guild.roles.fetch(roleId);
67	    return role;
68	  } catch (error) {
69	    logger.error('Failed to fetch Discord role', error);
70	    return null;
71	  }
72	};
73	
74	// ロールを作成
75	export const createRole = async (name: string): Promise<Role | null> => {
76	  try {
77	    const client = getDiscordClient();
78	    const guildId = getGuildId();
79	    const guild = await client.guilds.fetch(guildId);
80	    const role = await guild.roles.create({ name });
81	    logger.info(`Created role: ${name} (${role.id})`);
82	    return role;
83	  } catch (error) {
84	    logger.error('Failed to create Discord role', error);
85	    return null;
86	  }
87	};
88	
89	// メンバーにロールを付与
90	export const addRoleToMember = async (
91	  member: GuildMember,
92	  roleId: string
93	): Promise<boolean> => {
94	  try {
95	    await member.roles.add(roleId);
96	    logger.info(`Added role ${roleId} to member ${member.user.tag}`);
97	    return true;
98	  } catch (error) {
99	    logger.error('Failed to add role to member', error);
100	    return false;
101	  }
102	};
